"""Embedded app logo.

The square 256x256 logo is base64-encoded inside this module so the packaged
app needs no external asset files. The monogram is kept as a fallback.
"""
import base64

from PySide6.QtCore import Qt
from PySide6.QtGui import QIcon, QPixmap

_LOGO_B64 = """"""


def logo_pixmap(size):
    """Return the logo scaled to *size*x*size*, or None if it cannot load."""
    data = base64.b64decode(_LOGO_B64)
    pm = QPixmap()
    if pm.loadFromData(data, "PNG"):
        return pm.scaled(size, size, Qt.KeepAspectRatio, Qt.SmoothTransformation)
    return None


def logo_icon(size=64):
    pm = logo_pixmap(size)
    return QIcon(pm) if pm else QIcon()
